  'fts.title': "Volltextsuche für {table}",
  'fts.intro': "Fügt eine gespeicherte generierte tsvector-Spalte über die gewählten Textspalten hinzu, mit einem GIN-Index darauf. Eine Suchkonfiguration vom Suchtyp fulltext (Gemeinsame Komponenten › Suchkonfigurationen) oder die Suche eines Berichts findet dann Wortformen (\"running\" findet \"run\") schnell. Die Spalte aktualisiert sich selbst; das Hinzufügen schreibt die Tabelle neu.",
