  'st.app_type': 'Anwendungstyp',
  'st.app_type_help': 'Theme- und Bibliotheksanwendungen bieten ihr Theme oder ihre gemeinsamen Komponenten anderen Anwendungen an (Shared Components → Abonnements); Anwendung erstellen kann von einer Vorlagenanwendung ausgehen.',
