  'st.db_role': 'Datenbankrolle (Parsing-Schema)',
  'st.db_role_help': "Das gesamte SQL der Anwendung läuft als diese Rolle (SET LOCAL ROLE), daher gelten Berechtigungen und Row-Level-Security. Pflichtfeld (APEX: Parsing-Schema); kein Superuser, keine Rolle, die Row-Level-Security umgeht oder Rollen anlegt, und keine von pgkilns eigenen.",
  'st.debug': 'Debug-Modus',
  'st.debug_help': 'Zeigt Endbenutzern Details zu Datenbankfehlern. Nur für die Entwicklung.',
  'st.debug_msgs': 'Debug-Meldungen',
