  'st.debug_msgs_help': 'Zeichnet die Schritte jeder Anfrage mit Zeiten und die Meldungen von {fn} auf, aufbewahrt {days} Tage.',
  'st.header_title': 'Authentifizierung per HTTP-Header',
  'st.header_intro': 'Nur verwendet, wenn die Authentifizierung „HTTP-Header“ ist. Ein Reverse Proxy oder Single-Sign-on-Gateway meldet Benutzer an und übergibt den Benutzernamen in einem Header; pgkiln vertraut ihm nur von den Proxy-Adressen in {env}',
  'st.header_unset': 'auf diesem Server nicht gesetzt: Anmeldung per Header wird abgelehnt',
  'st.header_name': 'Header mit dem Benutzernamen',
  'st.header_name_help': 'Der Anfrage-Header mit dem Benutzernamen (APEX: HTTP Header Variable). Leer: X-Remote-User. Ein geänderter oder fehlender Header beendet die Sitzung.',
  'st.logout_url': 'Abmelde-URL',
  'st.logout_url_ph': 'z. B. https://sso.example.com/logout',
  'st.logout_url_help': 'Wohin „Abmelden“ nach dem Ende der Sitzung führt, meist die eigene Abmeldeseite des Proxys. Leer: eine Seite „abgemeldet“.',
  'st.header_auto': 'Konten automatisch anlegen',
  'st.header_auto_help': 'Ein unbekannter Benutzername erhält ein neues Konto mit Zugriff auf diese Anwendung. Sonst muss das Konto existieren und Zugriff haben.',
  'st.db_title': 'Datenbankkonten',
  'st.db_intro': 'Nur verwendet, wenn die Authentifizierung „Datenbankkonten“ ist. Benutzer melden sich mit einer PostgreSQL-Login-Rolle und deren Passwort an, geprüft durch eine kurze Verbindung zu dieser Datenbank als diese Rolle. Superuser und die eigenen Rollen von pgkiln werden immer abgelehnt; ohne eines der beiden Felder kann sich niemand anmelden.',
  'st.db_roles': 'Erlaubte Rollen',
  'st.db_roles_ph': 'z. B. alice, bob',
  'st.db_roles_help': 'Login-Rollen, die sich anmelden dürfen, durch Komma getrennt (genaue Namen).',
  'st.db_member': 'Oder Mitglieder der Rolle',
  'st.db_member_ph': 'z. B. app_users_group',
  'st.db_member_help': 'Jedes Mitglied dieser Rolle darf sich ebenfalls anmelden.',
  'st.custom_title': 'Eigene Authentifizierung',
  'st.custom_intro': 'Nur verwendet, wenn die Authentifizierung „Eigene“ ist. Ihr eigenes PL/pgSQL prüft Benutzername und Passwort des Anmeldeformulars, als Datenbankrolle der Anwendung; das Passwort wird als Parameter übergeben und nie protokolliert. Fehlversuche werden wie andere Anmeldungen gebremst. Ohne eines der beiden Felder kann sich niemand anmelden.',
  'st.custom_fn': 'Funktionsname',
  'st.custom_fn_ph': 'z. B. app.check_login',
  'st.custom_fn_help': 'Eine Funktion (p_username text, p_password text) returns boolean, in Kleinbuchstaben, optional mit Schema. Die Rolle der Anwendung braucht EXECUTE darauf. Hat Vorrang vor dem Funktionsrumpf unten.',
  'st.custom_body': 'Oder Funktionsrumpf',
  'st.custom_body_help': 'PL/pgSQL mit p_username und p_password, das bei einer gültigen Anmeldung true zurückgibt, z. B. {example}',
  'st.custom_post': 'Code nach der Authentifizierung',
  'st.custom_post_help': 'Optionales PL/pgSQL nach einer erfolgreichen Prüfung, mit p_username (und meta.app_user()), z. B. um die letzte Anmeldung zu speichern. Eine Exception lehnt die Anmeldung ab. Anwendungsprozesse „after login“ laufen danach wie gewohnt.',
  'st.signin': 'Anmeldung',
  'st.methods': 'Anmeldemethoden',
  'st.signin_page': 'Anmeldeseite',
  'st.staying': 'Angemeldet bleiben',
