  'st.add_one': 'Fügen Sie eines hinzu',
  'st.ldap_help': 'LDAP-Passwörter prüft das Formular mit Benutzername und Passwort, nach den lokalen Konten; lassen Sie diese Methode also aktiv.',
  'st.session_group': 'Gruppe für gemeinsame Sitzungen',
  'st.session_group_ph': 'leer: nicht geteilt',
  'st.session_group_help': 'Anwendungen mit derselben Gruppe (und dem Benutzerverzeichnis als Authentifizierung) teilen eine Anmeldung: Nach der Anmeldung bei einer öffnen sich die anderen ohne neue Anmeldung, jede mit eigener Zugriffsprüfung und eigenen Rollen; die Abmeldung bei einer meldet bei allen ab (APEX: Session Sharing). Kleinbuchstaben, Ziffern und _.',
  'st.remember': '„Angemeldet bleiben“ für (Tage)',
  'st.remember_ph': 'leer: nicht angeboten',
  'st.remember_help': 'Bietet ein Kontrollkästchen im Anmeldeformular (APEX: persistente Authentifizierung). Der Browser bleibt so viele Tage nach der Anmeldung angemeldet, auch wenn die Sitzung endet; Abmelden, ein neues Passwort, Deaktivierung oder entzogener Zugriff beenden es. 1 bis 365.',
