  'rs.saving_needs_a_process_of': 'Zum Speichern braucht diese Region einen Prozess vom Typ "grid_dml"; ohne ihn ist das Raster schreibgeschützt.',
  'rs.column_sum_avg_count_min': 'Spalte=sum, avg, count, min oder max; Spalten mit ";" trennen. Über alle Zeilen der Suche berechnet, nicht nur die Seite. Benutzer können eigene hinzufügen (Aktionen → Aggregat).',
  'rs.stay_in_view_while_the': 'Bleiben sichtbar, während das Raster seitlich scrollt. Benutzer können es ändern sowie Spalten verschieben, in der Größe ändern und ausblenden; "layout" im JSON legt Standardreihenfolge und -breiten fest.',
  'rs.views_users_may_switch_to': 'Ansichten, zu denen Benutzer neben dem Raster wechseln können. Die Einzelzeilenansicht bearbeitet jeweils eine Zeile (auch über das Zeilenaktionsmenü); Gruppieren und Diagramm werden unter Aktionen eingerichtet.',
  'rs.a_master_grid_s_selected': 'Die gewählte Zeile eines Master-Rasters legt ihren Wert in ein Seitenelement; Detailraster und Berichte verwenden ihn in ihrer Abfrage (:P1_ID) und werden ohne Neuladen der Seite aktualisiert. Andere Regionstypen folgen mit {"master": {"item": "P1_ID"}}.',
  'rs.edit_as_picks_a_shared': '"Bearbeiten als" wählt eine gemeinsame Werteliste (Gemeinsame Komponenten → Wertelisten) für eine Auswahlliste.',
  'rs.col_validations': 'Spaltenvalidierungen',
  'rs.col_validations_summary': 'Ein SQL-Ausdruck pro Spalte, den eine neue oder geänderte Zeile erfüllen muss',
  'rs.valid_when': 'Gültig, wenn (SQL-Ausdruck)',
  'rs.error_message': 'Fehlermeldung',
  'rs.aria_valid_when': 'Gültig, wenn, für {name}',
  'rs.aria_error_message': 'Fehlermeldung von {name}',
  'rs.col_validations_help': 'Der Ausdruck muss für eine hinzugefügte oder geänderte Zeile wahr sein. Die Spalten der Zeile sind Bind-Variablen mit ihren Namen in Großbuchstaben (:SAL, :COMM); Seitenelemente und :APP_USER funktionieren ebenfalls. Eine Zeile, die den Ausdruck nicht erfüllt, wird nicht gespeichert, und die Meldung erscheint in ihrer Zelle.',
  'rs.the_visible_area_and_vector': 'Der sichtbare Bereich und Vektorkacheln brauchen `lat`/`lng` (oder eine PostGIS-Geometrie) und laden neu, wenn die Karte bewegt wird. Vektorkacheln zeichnen Punkte, Linien und Flächen, ohne Gruppierung oder Liste.',
  'rs.the_same_columns_as_the': 'Dieselben Spalten wie die Abfrage der Karte. Leeren Sie die Abfrage, um die Ebene zu entfernen.',
  'rs.the_condition_runs_on_the': 'Die Bedingung läuft auf dem Server: mit installiertem PostGIS auf einer geometry/geography-Spalte, sonst auf Breite und Länge.',
  'rs.users_switch_between_the_ticked': 'Benutzer wechseln zwischen den angehakten Ansichten. Stunden außerhalb des Bereichs werden ergänzt, wenn ein Ereignis sie braucht.',
  'rs.runs_as_the_application_s': 'Läuft als Datenbankrolle der Anwendung (Sicherheit auf Zeilenebene gilt) mit `:EVENT_ID` (Wert der Schlüsselspalte), `:NEW_START` und `:NEW_END` (gleiche Dauer wie vorher). Leer: Ereignisse lassen sich nicht ziehen.',
  'rs.only_events_the_user_sees': 'Nur Ereignisse, die der Benutzer in diesem Kalender sieht, lassen sich verschieben; ohne Maus ändert der Bearbeitungslink die Daten.',
  'rs.not_while_the_pointer_or': 'Nicht, solange Zeiger oder Fokus im Karussell sind, und nicht für Benutzer, die reduzierte Bewegung bevorzugen. Ein Karussell hat kein "Alle anzeigen".',
  'rs.a_chosen_region_gets_display': 'Eine gewählte Region erhält `"display_selector": true` in ihren Einstellungen (ein Reiter nach ihr benannt) oder den Reiternamen: Regionen mit demselben Reiternamen teilen sich einen Reiter (z. B. Smart Filters und ihr Bericht). Ohne JavaScript werden alle Regionen angezeigt, mit Links zu jeder.',
  'rs.gauge_charts_only_a_warning': 'Nur Messanzeige-Diagramme. Liegt die Warnschwelle über der kritischen, sind niedrige Werte schlecht (z. B. Warnung 50, kritisch 20).',
  'rs.drill_down_column_takes_the': 'Drilldown: `#column#` nimmt den Wert aus der Zeile des Punkts, `#series#` den Namen seiner Reihe. Spalten, auf die nur der Link verweist, werden nicht gezeichnet.',
  'rs.gantt_charts_with_a_task': 'Gantt-Diagramme mit einer Spalte `task_id`. Läuft als Datenbankrolle der Anwendung (Sicherheit auf Zeilenebene gilt) mit `:TASK_ID`, `:NEW_START` und `:NEW_END` (`YYYY-MM-DD` oder stundenweise `YYYY-MM-DDTHH:MM`; ein Meilenstein erhält gleichen Start und gleiches Ende). Leer: Aufgaben lassen sich nicht ziehen.',
  'rs.only_tasks_the_user_sees': 'Nur Aufgaben, die der Benutzer in diesem Diagramm sieht, lassen sich verschieben; danach wird das Diagramm neu aus seiner Abfrage gezeichnet.',
