  'rs.no_position_alert': 'Der Bericht hat keine Spalten `lat`/`lng` oder `location`, daher kann der Kartenbereich ihn nicht filtern.',
  'rs.facets_help': 'Kontrollkästchen zeigen die häufigsten Werte (mit Ausschließen filtern Benutzer sie stattdessen heraus). Bereiche und Von/bis brauchen eine Zahl- oder Datumsspalte: Bereiche sind `from..to = label`, getrennt durch `;`, ein offenes Ende bleibt leer (`..1000`, `2020-01-01..`); ein Bereich schließt seinen Anfang ein, nicht sein Ende. Eine Sternebewertung bietet „4 Sterne und mehr“ usw. (bis 5; `"max"` im JSON ändert das).',
  'rs.facets_help_chart': 'Diagramm: ein Balken- oder Kreisdiagramm der Anzahlen unter der Facette (eingeklappt); ein Balken oder Segment filtert nach seinem Wert.',
  'rs.calendar_help': 'Die Abfrage liefert `start_date`, `title` und optional `end_date` (Datumswerte für ganztägige Termine, Zeitstempel für Termine mit Uhrzeit).',
  'rs.chart_help': 'Die erste Spalte ist die Beschriftung; jede folgende numerische Spalte ist eine Reihe (bis zu 8). Ein Gantt-Diagramm liest `label, start, end` (Datum oder Zeitstempel; ein leeres Ende ist ein Meilenstein) und optionale Spalten namens `progress` (0 bis 100), `task_id` und `depends_on` (die IDs, auf die eine Aufgabe wartet, z. B. `3,4`).',
  'rs.map_help': 'Jede Zeile ist eine Markierung bei `lat`, `lng` (oder `location` als "lat,lng"), mit `title` und `body` im Popup; eine Spalte `geojson` zeichnet Linien und Flächen (mit installiertem PostGIS geht auch eine Spalte `geometry` oder `geography` in WGS 84). Eine Heatmap gewichtet jeden Ort nach einer Spalte `weight`.',
  'rs.tree_help': 'Die Abfrage liefert `id`, `parent_id` und `label` (und optional `icon`); Zeilen, deren Elternzeile nicht im Ergebnis ist, sind die Wurzeln.',
  'rs.workflow_help': 'Workflows stammen aus Workflow-Definitionen (Gemeinsame Komponenten); Anwendungs-SQL startet sie mit `meta.start_workflow(…)`.',
  'rs.task_help': 'Aufgaben stammen aus Aufgabendefinitionen (Gemeinsame Komponenten); Anwendungs-SQL erstellt sie mit `meta.create_task(…)`.',
