  'wres.files_intro': 'CSS, JavaScript, JSON, Bilder und Schriften, die jede Anwendung von {workspace} verwenden darf: Eine Anwendung lädt eine auf jeder Seite mit {tag} unter Gemeinsame Komponenten → Statische Anwendungsdateien → Jede Seite lädt (eine Seite: Seite → Darstellung), und Vorlagen, HTML und Links verwenden {sub} für ihre URL. Jede Anwendung liefert sie unter ihrer eigenen Adresse aus ({path}), nie die eines anderen Workspace. Bis {size} pro Datei; kein HTML. Sie reisen mit dem Workspace-Export.',
  'wres.type_help': 'basic: Benutzername + Passwort · header: ein HTTP-Header mit dem Geheimnis (API-Schlüssel) · bearer: Authorization: Bearer <secret> · oauth2: Client Credentials, Password oder Refresh Token Grant · aws_sigv4: ein S3-kompatibler Objektspeicher.',
  'wres.credentials_intro': 'Web-Zugangsdaten von {workspace}, die seine Anwendungen namentlich in REST-Datenquellen, dem Prozess „API aufrufen“, Remote-Servern und Objektspeichern verwenden, sodass ein Schlüssel einmal für den Workspace eingegeben wird. Eigene Zugangsdaten einer Anwendung (Gemeinsame Komponenten → Web-Zugangsdaten) mit demselben Namen haben Vorrang. Geheimnisse werden mit dem Schlüssel des Servers verschlüsselt, nie wieder angezeigt und nie exportiert.',
