  'asst.who_the_assistant_is_and': 'Wer der Assistent ist und was er beantworten darf. `&ITEM.` wird durch den Wert des Elements als abgegrenzte Daten ersetzt (nie die Session-ID oder Passwörter).',
  'asst.run_before_each_question_their': 'Vor jeder Frage ausgeführt; ihre Zeilen gehen als Daten an das Modell. `[{"name": "policy", "sql": "select title, body from hr.policy where body @@ plainto_tsquery(:AI_PROMPT)", "max_rows": 5}]` (`:AI_PROMPT` ist die Frage, `:APP_USER` und Elemente wie üblich).',
  'asst.the_model_calls_them_when': 'Das Modell ruft sie auf, wenn es sie braucht. SQL: `{"name": "my_leave", "description": "…", "sql": "select … where status = :STATUS", "parameters": {"STATUS": {"type": "string", "enum": ["PENDING", "APPROVED"]}}}`; fügen Sie `"writes": true` für ein Werkzeug hinzu, das Daten ändert, und `"authz": "SCHEME"`, um es nur manchen Benutzern anzubieten. REST: `{"name": "department", "type": "rest", "source": "DEPARTMENT", "description": "…", "parameters": {"dname": {"type": "string"}}}`. Parametertypen: string, integer, number, boolean, date; `"optional": true` erlaubt keinen Wert.',
  'asst.agent_help': 'Ein Agent aus {link} legt Dienst, System-Prompt, Denkaufwand, Werkzeuge und Schritte fest; Speichern mit einem Agenten entfernt den eigenen Dienst, System-Prompt, die Werkzeuge und Werkzeugrunden der Region.',
