  'asst.no_agent': 'Es gibt keinen KI-Agenten {agent}.',
  'asst.filter_intro': 'Benutzer geben eine Frage ein; sie wird zu den eigenen Einstellungen des Berichts (Filter, Hervorhebungen, Sortierung, Gruppenwechsel, Summen, Gruppierung, Pivot, Diagramm, berechnete Spalten; nur Spalten, die der Bericht zeigt, nur seine Operatoren), angezeigt als Chips, die sie bearbeiten, entfernen oder rückgängig machen können. Mit einem KI-Dienst gehen die Frage und die Spaltennamen an den Anbieter des Dienstes; ohne ({builtin}) liest pgkiln gängige Formulierungen selbst, auf Englisch, Niederländisch und Deutsch.',
