  // ------------------------------------------------------------ JSON sources (sprint 164)
  'jsrc.a_column_per_path_in': 'Eine Spalte pro Pfad im Dokument (Schlüssel durch Punkte getrennt, z. B. `address.city`). Ein Wert, der sich nicht als der Typ lesen lässt, erscheint leer. Beim Speichern einer Zeile werden nur die Pfade geschrieben, deren Werte sich geändert haben: Schlüssel, die diese Liste nicht nennt, bleiben im Dokument. Leeren Sie einen Namen, um eine Spalte zu entfernen.',
