  'jsrc.for_a_table_of_documents': 'Für eine Dokumenttabelle: Ein Insert in die View fügt eine Zeile hinzu, ein Delete entfernt sie. Aus: Die View ändert nur die Dokumente vorhandener Zeilen.',
