  'jsrc.json_sources': 'JSON-Quellen',
  'jsrc.a_json_source_describes_a': 'Eine JSON-Quelle beschreibt eine jsonb-Spalte: eine Spalte pro Pfad in ihren Dokumenten und Arrays von Objekten als eigene Zeilen. pgkiln erstellt daraus aktualisierbare Views, sodass Formulare, Berichte, interaktive Raster, REST und MCP die Dokumente wie Tabellen lesen und schreiben. Das Speichern einer Zeile ändert nur die Pfade, die sie geändert hat: Schlüssel, die die Quelle nicht kennt, bleiben. Für eine Tabelle mit ihren Kindtabellen als ein Dokument siehe SQL Workshop › Tabelleneigenschaften › Dokument-View.',
