  'agt.sql_help': 'Ein SELECT mit den Parametern als :NAME-Bind-Werte (und :APP_USER, Elemente). Läuft als Datenbankrolle der Anwendung (Berechtigungen und Row Level Security gelten) in einer schreibgeschützten Transaktion.',
