  'agt.f_timeout': 'Zeitlimit',
  'agt.intro': 'Ein Agent antwortet in einer KI-Assistent-Region und handelt nur über die Werkzeuge, die Sie ihm geben: SQL-Abfragen (schreibgeschützt, als Datenbankrolle der Anwendung, sodass Row Level Security gilt), PL/pgSQL-Funktionen, REST-Datenquellen, JavaScript-Aktionen im Browser und Links zu Seiten (pgkiln erstellt die URL und ihre Prüfsumme, nur für Seiten, die der Benutzer öffnen darf). Ein Retrieve-Werkzeug gibt dem Agenten die Zeilen einer Suchkonfiguration, die inhaltlich zu einem Text passen (RAG), wiederum als Rolle der Anwendung. Was Benutzer eingeben und die Ergebnisse der Werkzeuge gehen an den KI-Dienst des Agenten. {usage} listet jeden Werkzeugaufruf.',
