  'tel.send_traces_logs_and_metrics': 'Senden Sie Traces, Logs und Metriken der Anwendungen über einen OpenTelemetry Collector an Ihr eigenes Monitoring (Grafana, Jaeger, Datadog, Honeycomb, OCI APM oder alles, was OTLP spricht). Ein Trace pro Seitenanfrage, mit einem Span für jede SQL-Anweisung, jeden Aufruf einer REST-Datenquelle, jede KI-Anfrage und jeden Tool-Aufruf; Mail- und Workflow-Schritte als eigene Traces. pgkiln sendet OTLP über HTTP als JSON. Die üblichen `OTEL_*`-Umgebungsvariablen funktionieren ebenfalls; ein hier gesetzter Wert hat Vorrang. Kapitel 1 des Handbuchs (Monitoring mit OpenTelemetry) erklärt jede Wahl.',
