  'gal.empty': 'Die Galerie ist leer.',
  'gal.intro.samples': 'Anwendungen, die zeigen, was pgkiln kann, jeweils mit eigenem Schema, Daten und Demokonto: das Schaufenster, das Tutorial, eine App pro Funktionsbereich und der UX Pattern Catalog. Ein Administrator installiert sie auf einer Entwicklungs- oder Demoinstanz.',
  'gal.intro.starters': 'Kleine, sofort einsetzbare Anwendungen. Installieren zeigt, was erstellt wird (Tabellen, Seiten, Beispieldaten), bevor etwas passiert; die Anwendung erhält in diesem Workspace eine eigene Rolle und ein eigenes Schema.',
  'gal.intro.utilities': 'Anwendungen, die ein Workspace nutzt, statt aus ihnen zu lernen: gemeinsame Nachschlagelisten, Versionshinweise, Ankündigungen. Wie bei Starter-Apps zeigt Installieren zuerst, was erstellt wird, und die Anwendung erhält in diesem Workspace eine eigene Rolle und ein eigenes Schema.',
